def addresses(self) -> list[Any]:
    ret: list[Any] = []
    for site in self._sites:
        server = site._server
        if server is not None:
            sockets = server.sockets
            if sockets is not None:
                for sock in sockets:
                    ret.append(sock.getsockname())
    return ret

new_text:
def addresses(self) -> list[Any]:
    ret: list[Any] = []
    for site in self._sites:
        server = site._server
        if server is not None:
            sockets = server.sockets  # type: ignore[attr-defined]
            if sockets is not None:
                for sock in sockets:
                    ret.append(sock.getsockname())
    return ret
